// Authored harness fixture; not an engine-created game or player feedback.
const fs=require('fs'),crypto=require('crypto'),{chromium}=require('/opt/tsr/node_modules/playwright');
(async()=>{const assets=new Map(['index.html','app.js'].map(n=>[n,fs.readFileSync('/project/'+n)]));const browser=await chromium.launch({headless:true,chromiumSandbox:false});try{const context=await browser.newContext({serviceWorkers:'block',acceptDownloads:false});await context.route('**/*',r=>{const u=new URL(r.request().url()),n=u.pathname.slice(1);return u.origin==='http://tsr.invalid'&&assets.has(n)?r.fulfill({body:assets.get(n),contentType:n.endsWith('.html')?'text/html':'text/javascript'}):r.abort();});const page=await context.newPage();await page.goto('http://tsr.invalid/index.html');await page.click('#start');await page.keyboard.press('ArrowRight');const text=await page.locator('#readout').innerText();console.log(JSON.stringify({version:'authored-control-assessment',source:Object.fromEntries([...assets].map(([n,b])=>[n,crypto.createHash('sha256').update(b).digest('hex')])),checks:[{name:'authored real keyboard control',pass:text.includes('moves 1')&&text.includes('score 1'),observed:text}]}));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exit(1)});
